CodeAssembler& CodeAssemblerFns3::sub(AsmMemoryOperand op0, std::int32_t op1) {
	Code code;
	if (op0.size() == MemoryOperandSize::Qword) {
		if ((op1 >= -0x80 && op1 <= 0x7F)) {
			code = Code::Sub_rm64_imm8;
		} else {
			code = Code::Sub_rm64_imm32;
		}
	} else if (op0.size() == MemoryOperandSize::Dword) {
		if ((op1 >= -0x80 && op1 <= 0x7F)) {
			code = Code::Sub_rm32_imm8;
		} else {
			code = Code::Sub_rm32_imm32;
		}
	} else if (op0.size() == MemoryOperandSize::Word) {
		if ((op1 >= -0x80 && op1 <= 0x7F)) {
			code = Code::Sub_rm16_imm8;
		} else {
			code = Code::Sub_rm16_imm16;
		}
	} else if (op0.size() == MemoryOperandSize::Byte) {
		code = Code::Sub_rm8_imm8;
	} else {
		return set_error("sub: invalid operands");
	}
	return add_instr(Instruction::with2(code, to_memory_operand(op0), op1));
}

